public class Compiler_toSource_TriageGen1Test {

    private Compiler compiler;
    private CompilerOptions options;
    private CodeBuilder cb;
    private Node root;

    @Before
    public void setUp() {
        compiler = spy(new Compiler());
        options = new CompilerOptions();
        compiler.initOptions(options);
        cb = new CodeBuilder();
        root = mock(Node.class);

        // The method uses runInCompilerThread. In unit tests, we want to execute 
        // the Callable immediately on the same thread.
        doAnswer(new Answer<Void>() {
            @Override
            public Void answer(InvocationOnMock invocation) throws Throwable {
                java.util.concurrent.Callable<Void> callable = invocation.getArgument(0);
                callable.call();
                return null;
            }
        }).when(compiler).runInCompilerThread(any(java.util.concurrent.Callable.class));
    }

    @Test
    public void testToSource_NoDelimiterNoLicenseNoCode() {
        options.printInputDelimiter = false;
        when(root.getJSDocInfo()).thenReturn(null);
        // Mock the internal toSource(Node, SourceMap, boolean) via compiler spy or handling
        // Since we can't easily mock the private/protected toSource(Node...) without complex setup,
        // we assume the compiler is in a state where toSource(root, ...) returns empty.
        // However, to make this testable, we'll rely on the fact that if the internal call 
        // returns "", nothing is appended.

        // We use a partial mock/spy to control the result of the internal toSource call
        doAnswer(invocation -> {
            cb.append(""); 
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 0, root);
        assertThat(cb.toString()).isEmpty();
    }

    @Test
    public void testToSource_WithDelimiterAndLicense() throws Exception {
        options.printInputDelimiter = true;
        options.inputDelimiter = "File: %name% Num: %num%";

        when(root.getType()).thenReturn(Token.SCRIPT);
        when(root.getSourceFileName()).thenReturn("test.js");

        JSDocInfo jsDocInfo = mock(JSDocInfo.class);
        when(jsDocInfo.getLicense()).thenReturn("MIT License");
        when(root.getJSDocInfo()).thenReturn(jsDocInfo);

        // Mock internal toSource call to return code that needs a semicolon
        doAnswer(invocation -> {
            cb.append("var x = 1"); // missing semicolon
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 5, root);

        String expected = "File: test.js Num: 5\n" +
                          "/*\nMIT License*/\n" +
                          "var x = 1;";
        assertThat(cb.toString()).isEqualTo(expected);
    }

    @Test
    public void testToSource_WithDelimiterNewLines() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "Header";
        cb.append("existing"); // No newline at end

        when(root.getType()).thenReturn(Token.SCRIPT);
        when(root.getSourceFileName()).thenReturn("file.js");
        when(root.getJSDocInfo()).thenReturn(null);

        doAnswer(invocation -> {
            cb.append("code;");
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 1, root);

        // Should have appended \n after "existing", then "Header\n", then "code;"
        assertThat(cb.toString()).isEqualTo("existing\nHeader\ncode;");
    }

    @Test
    public void testToSource_WithSemicolonHeuristic() {
        options.printInputDelimiter = false;
        when(root.getJSDocInfo()).thenReturn(null);

        // Case 1: Ends with semicolon
        doAnswer(invocation -> {
            cb.append("var x = 1;");
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 0, root);
        assertThat(cb.toString()).isEqualTo("var x = 1;");

        // Case 2: Ends with newline and semicolon on previous line
        cb = new CodeBuilder();
        doAnswer(invocation -> {
            cb.append("var x = 1;\n");
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 0, root);
        assertThat(cb.toString()).isEqualTo("var x = 1;\n");

        // Case 3: Single char code (no second last char)
        cb = new CodeBuilder();
        doAnswer(invocation -> {
            cb.append(";");
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 0, root);
        assertThat(cb.toString()).isEqualTo(";");
    }

    @Test
    public void testToSource_SourceMapPositioning() {
        options.sourceMapOutputPath = "map.txt";
        options.printInputDelimiter = false;
        when(root.getJSDocInfo()).thenReturn(null);

        // Mocking SourceMap behavior via the actual compiler's sourceMap field if possible, 
        // but since it's internal, we check if the method doesn't crash and 
        // we'd ideally verify the call via a spy if sourceMap was accessible.
        // Given the constraints, we ensure logic path is covered.

        doAnswer(invocation -> {
            cb.append("code");
            return null;
        }).when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

        compiler.toSource(cb, 0, root);
        assertThat(cb.toString()).isEqualTo("code;");
    }

    @Test
    public void testToSource_PreconditionFailures() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "delim";

        // Fail root type check
        when(root.getType()).thenReturn(Token.EXPRESSION);
        assertThrows(IllegalStateException.class, () -> compiler.toSource(cb, 0, root));

        // Fail source name check
        when(root.getType()).thenReturn(Token.SCRIPT);
        when(root.getSourceFileName()).thenReturn(null);
        assertThrows(IllegalStateException.class, () -> compiler.toSource(cb, 0, root));

        // Fail empty source name check
        when(root.getSourceFileName()).thenReturn("");
        assertThrows(IllegalStateException.class, () -> compiler.toSource(cb, 0, root));
    }

    // Helper to allow mocking the internal toSource call which is used by the method being tested
    private static class JSDocInfo {
        public String getLicense() { return null; }
    }
}
